import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"AL Objects and Object IDs","description":"","frontmatter":{},"headers":[],"relativePath":"your-first-al-programs/al-objects-and-object-ids.md","filePath":"your-first-al-programs/al-objects-and-object-ids.md"}`),a={name:`your-first-al-programs/al-objects-and-object-ids.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="al-objects-and-object-ids" tabindex="-1">AL Objects and Object IDs <a class="header-anchor" href="#al-objects-and-object-ids" aria-label="Permalink to “AL Objects and Object IDs”">​</a></h1><h2 id="what-are-al-objects" tabindex="-1">What Are AL Objects? <a class="header-anchor" href="#what-are-al-objects" aria-label="Permalink to “What Are AL Objects?”">​</a></h2><p>In AL, an <strong>object</strong> is a building block used to define a particular part of Business Central&#39;s functionality.</p><p>For example, a table defines how data is structured, while a page defines how users interact with that data.</p><p>Common AL objects include:</p><table tabindex="0"><thead><tr><th>Object</th><th>Purpose</th></tr></thead><tbody><tr><td><code>table</code></td><td>Defines the structure of stored data.</td></tr><tr><td><code>page</code></td><td>Defines the user interface.</td></tr><tr><td><code>codeunit</code></td><td>Contains reusable business logic.</td></tr><tr><td><code>report</code></td><td>Generates reports and documents.</td></tr><tr><td><code>tableextension</code></td><td>Extends an existing table with additional fields or functionality.</td></tr><tr><td><code>pageextension</code></td><td>Extends an existing page with additional functionality.</td></tr><tr><td><code>enum</code></td><td>Defines a set of named values.</td></tr></tbody></table><p>For example, a simple table object might look like this:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>table 50100 Employee</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    fields</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        field(1; &quot;Employee Name&quot;; Text[100])</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    keys</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        key(PK; &quot;Employee Name&quot;)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Clustered = true;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here, we define a table named <code>Employee</code> that contains an <code>Employee Name</code> field.</p><h2 id="what-are-object-ids" tabindex="-1">What Are Object IDs? <a class="header-anchor" href="#what-are-object-ids" aria-label="Permalink to “What Are Object IDs?”">​</a></h2><p>Every AL object that requires an ID has a numeric identifier that distinguishes it from other objects of the same object type.</p><p>Consider this declaration:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>table 50100 Employee</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // Table definition</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>It contains three important parts:</p><ul><li><code>table</code> — specifies the object type.</li><li><code>50100</code> — specifies the object ID.</li><li><code>Employee</code> — specifies the object name.</li></ul><p>Object IDs help Business Central identify objects internally. The object name makes them easier for developers to recognize.</p><h3 id="are-object-ids-unique" tabindex="-1">Are Object IDs Unique? <a class="header-anchor" href="#are-object-ids-unique" aria-label="Permalink to “Are Object IDs Unique?”">​</a></h3><p>Object IDs must be unique within their respective object types in a given application context.</p><p>For example, you cannot define two different tables with ID <code>50100</code> in the same application context.</p><p>However, a table and a page can both use ID <code>50100</code> because they are different object types.</p><h2 id="understanding-object-id-ranges" tabindex="-1">Understanding Object ID Ranges <a class="header-anchor" href="#understanding-object-id-ranges" aria-label="Permalink to “Understanding Object ID Ranges”">​</a></h2><p>Business Central uses different object ID ranges for different purposes.</p><p>When developing custom extensions, you should use an ID range allocated to your extension rather than choosing IDs that conflict with other objects.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>table 50100 Employee</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // Employee data</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>page 50101 EmployeeList</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // Employee list interface</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here, we use IDs <code>50100</code> and <code>50101</code> for our custom objects.</p><p><strong>Important:</strong> The IDs available to you depend on your application&#39;s configuration and licensing or development arrangements. Check the permitted ID ranges before creating custom objects.</p><h3 id="table-extensions-and-page-extensions" tabindex="-1">Table Extensions and Page Extensions? <a class="header-anchor" href="#table-extensions-and-page-extensions" aria-label="Permalink to “Table Extensions and Page Extensions?”">​</a></h3><p>Extension objects work differently from regular objects.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tableextension 50100 CustomerExtension extends Customer</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    fields</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        field(50100; &quot;Customer Rating&quot;; Integer)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here:</p><ul><li><code>tableextension</code> specifies the object type.</li><li><code>50100</code> is the table extension&#39;s object ID.</li><li><code>CustomerExtension</code> is its name.</li><li><code>extends Customer</code> specifies the existing table being extended.</li><li><code>field(50100; ...)</code> defines a new field with its own field ID.</li></ul><p>Notice that the table extension&#39;s ID and its field&#39;s ID are separate identifiers. They belong to different ID contexts.</p><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to “Key Takeaway”">​</a></h2><p><strong>AL objects are the building blocks of Business Central, while object IDs identify individual objects within their respective types.</strong> When creating custom objects, choose IDs from an appropriate range and ensure they do not conflict with existing objects.</p>`,36)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};